const {test,expect}=require('@playwright/test');
async function setup(page){
 await page.route('http://127.0.0.1:8001/**',r=>r.fulfill({json:[]}));
 await page.route('**/api/bible/**',r=>{
  const path=new URL(r.request().url()).pathname,b={id:1,osis_id:'Gen',name_en:'Genesis',name_he:'בראשית',testament:'OT',book_order:1};
  return r.fulfill({json:path.endsWith('/books')?{data:[b],total:1}:path.endsWith('/verses')?{data:[{id:1,verse_num:1,book_id:1,chapter_num:1,words:[{id:1,position:1,surface_he:'בְּרֵאשִׁית',display_he:'בְּרֵאשִׁית',lemma_strong:null,morph_code:null}]}],total:1}:{...b,chapters:[{id:1,chapter_num:1},{id:2,chapter_num:2}]}});
 });
 await page.goto('/');
}
const tabs=page=>page.getByRole('tablist',{name:'Workspace tabs'}).getByRole('tab');
async function add(page){await page.getByRole('button',{name:'New workspace tab',exact:true}).click();await page.getByRole('dialog',{name:'Book and chapter selector'}).getByRole('button',{name:'Cancel',exact:true}).click();}
test('real IndexedDB reload restores two public setups',async({page})=>{
 await setup(page);await add(page);await expect(tabs(page)).toHaveCount(2);
 await page.waitForTimeout(600);await page.reload();await expect(tabs(page)).toHaveCount(2);
});
test('closed codec bounds privacy expiry and future version policy',async({page})=>{
 await setup(page);
 const result=await page.evaluate(async()=>{
  const m=await import('/src/lib/workspace-storage.ts');
  const pane={paneKey:'pane',ref:{version:1,book_id:'Gen',target:{kind:'chapter',chapter:1}}};
  // Use the actual controller's public grammar instead of duplicating references.
  document.querySelector('[aria-label="New workspace tab"]').click();
  const snapshot=history.state.usr.scribeswellReader;
  const publicRecord={v:1,updated:Date.now(),activeTabKey:snapshot.tabKey,tabs:[{...snapshot,incarnation:'life',invalid:false}]};
  return {good:!!m.parsePublic(publicRecord),bad:!!m.parsePublic({...publicRecord,body:'private'}),expired:!!m.parsePublic({...publicRecord,updated:Date.now()-31*86400000}),future:m.isFuture({v:2})};
 });expect(result).toEqual({good:true,bad:false,expired:false,future:true});
});
const account='10000000-0000-4000-8000-000000000001',other='10000000-0000-4000-8000-000000000002',study='30000000-0000-4000-8000-000000000001',note='40000000-0000-4000-8000-000000000001';
const session={access_token:'owner-token',refresh_token:'fixture',expires_at:Math.floor(Date.now()/1000)+3600,expires_in:3600,token_type:'bearer',user:{id:account,email:'fixture@example.invalid',aud:'authenticated',app_metadata:{},user_metadata:{}}};
const catalogue=require('../src/generated/reference-catalogue.json');
const reference={catalogue_id:catalogue.catalogue_id,catalogue_version:catalogue.catalogue_version,versification_id:catalogue.books[0].versification_id,book_id:'Gen',target:{kind:'chapter',chapter:1}};
function publicSetup(count=2){return {v:1,updated:Date.now(),activeTabKey:'saved-0',tabs:Array.from({length:count},(_,i)=>({v:1,tabKey:`saved-${i}`,incarnation:`life-${i}`,activePaneKey:`pane-${i}`,panes:[{paneKey:`pane-${i}`,ref:reference}],invalid:false}))};}
function privateSetup(count=2){return {v:1,updated:Date.now(),account,tabs:Array.from({length:count},(_,i)=>({tabKey:`saved-${i}`,incarnation:`life-${i}`,study,note,label:`Private label ${i+1}`}))};}
async function seed(page,pub=publicSetup(),priv){await page.route('**/__workspace-storage-fixture',route=>route.fulfill({contentType:'text/html',body:'<!doctype html><title>Storage fixture</title>'}));await page.goto('/__workspace-storage-fixture');await page.evaluate(async({pub,priv})=>{const {workspaceDatabase}=await import('/src/lib/workspace-storage.ts');await new Promise((resolve,reject)=>{const r=indexedDB.open(workspaceDatabase,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('metadata'))r.result.createObjectStore('metadata');};r.onerror=reject;r.onsuccess=()=>{const db=r.result,tx=db.transaction('metadata','readwrite');tx.objectStore('metadata').put(pub,'public');if(priv)tx.objectStore('metadata').put(priv,`account:${priv.account}`);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=reject;};});},{pub,priv});}
async function stored(page){return page.evaluate(async()=>{const {workspaceDatabase}=await import('/src/lib/workspace-storage.ts');return new Promise((resolve,reject)=>{const r=indexedDB.open(workspaceDatabase,1);r.onsuccess=()=>{const db=r.result,tx=db.transaction('metadata'),s=tx.objectStore('metadata'),a=s.getAll(),b=s.getAllKeys();tx.oncomplete=()=>{db.close();resolve(Object.fromEntries(b.result.map((key,i)=>[key,a.result[i]])));};tx.onerror=reject;};r.onerror=reject;});});}
async function owner(page,options={}){
 let reads=0,active=0,max=0;
 await page.route('**/auth/v1/user*',async r=>{if(options.identity)await options.identity(r);else await r.fulfill({json:session.user});});
 await page.route('**/auth/v1/logout*',r=>r.fulfill({json:{}}));
 await page.route('**/api/operations/**',r=>r.fulfill({json:{status:'unresolved'}}));
 await page.route('**/api/studies**',async r=>{
  reads++;active++;max=Math.max(active,max);try{
   if(r.request().method()!=='GET'&&!(options.read&&new URL(r.request().url()).pathname.endsWith('/search')))return await r.fulfill({status:503,json:{code:'studies_storage_unavailable'}});
   if(options.read)return await options.read(r);
   const path=new URL(r.request().url()).pathname;
   const selected={id:study,owner_account_id:account,title:'Secret study title',revision:'1'};
   const selectedNote={id:note,study_id:study,owner_account_id:account,revision:'1',visibility:'study',value:{document:{version:1,blocks:[{type:'paragraph',direction:'auto',content:[{type:'text',text:'Saved private body',marks:[]}]}]},connections:[],highlights:[]}};
   return await r.fulfill({json:path.endsWith('/notes/'+note)?selectedNote:path.endsWith('/'+study)?selected:{items:[selected],next_cursor:null}});
  }finally{active--;}
 });
 await page.evaluate(s=>localStorage.setItem('pts-auth',JSON.stringify(s)),session);
 return {reads:()=>reads,max:()=>max};
}
