 await page.getByRole('button',{name:'Analysis',exact:true}).click();await expect(page.getByRole('textbox',{name:'Note text',exact:true})).toContainText('Saved private body');await tabs(page).nth(1).click();await page.getByRole('button',{name:'Analysis',exact:true}).click();await expect(page.locator('[aria-label="Note text"]')).toHaveCount(1);
 await page.waitForTimeout(600);const records=await stored(page),pub=JSON.stringify(records.public),all=JSON.stringify(records);for(const forbidden of ['Private label','owner-token','Saved private body','Secret study title','owner_account_id','connections','highlights','selection'])expect(pub).not.toContain(forbidden);for(const forbidden of ['owner-token','Saved private body','Secret study title','owner_account_id','connections','highlights'])expect(all).not.toContain(forbidden);expect(JSON.stringify(await page.evaluate(()=>history.state))+page.url()).not.toContain('Private label');expect(records[`account:${account}`].tabs).toHaveLength(2);
