 await page.addInitScript(kind=>{if(kind==='quota')IDBObjectStore.prototype.put=function(){throw new DOMException('fixture','QuotaExceededError');};else if(kind==='blocked')indexedDB.open=function(){const request={};setTimeout(()=>request.onblocked?.(new Event('blocked')),20);return request;};else indexedDB.open=function(){throw new DOMException('fixture','SecurityError');};},kind);
