 await add(page);await settled(page);const firstLive=await tabs(page).evaluateAll(nodes=>nodes.map(node=>node.dataset.workspaceTab));expect(await tabs(second).evaluateAll(nodes=>nodes.map(node=>node.dataset.workspaceTab))).toEqual(initialSecond);
 await add(second);await settled(second);const winner=(await stored(second)).public;expect(await tabs(page).evaluateAll(nodes=>nodes.map(node=>node.dataset.workspaceTab))).toEqual(firstLive);
