 await decision.getByRole('button',{name:/Close remembered tab 3:/}).click();await expect(decision).toBeVisible();await decision.getByRole('button',{name:/Close remembered tab 3:/}).click();await expect(tabs(page)).toHaveCount(12);for(const key of current)expect(await tabs(page).evaluateAll(nodes=>nodes.map(node=>node.dataset.workspaceTab))).toContain(key);
