async function holdProviderWrites(page){
 await page.evaluate(()=>{const original=IDBDatabase.prototype.transaction;window.providerWrites=[];IDBDatabase.prototype.transaction=function(...args){const tx=original.apply(this,args);if(args[1]==='readwrite'&&window.providerWrites.length<2){const entry={keep:true,tx};window.providerWrites.push(entry);const pump=()=>{const request=tx.objectStore('metadata').get('provider-keepalive');request.onsuccess=()=>{if(entry.keep)pump();};};pump();}return tx;};window.abortProviderFirst=()=>{window.providerWrites[0].keep=false;window.providerWrites[0].tx.abort();};window.finishProviderSecond=()=>{window.providerWrites[1].keep=false;};});
}
for(const newerReadFailure of [false,true])test(`provider queued success ${newerReadFailure?'preserves a newer read failure':'recovers suppression before the third changed projection'}`,async({page})=>{
 await setup(page);await settled(page);const clockStart=Date.now();await page.clock.install({time:clockStart});await page.clock.pauseAt(clockStart+1000);await holdProviderWrites(page);await add(page);await page.clock.fastForward(250);await expect.poll(()=>page.evaluate(()=>window.providerWrites.length)).toBe(1);await add(page);await page.clock.fastForward(250);await page.evaluate(()=>window.abortProviderFirst());const notice=page.getByRole('status').filter({hasText:'Reading setup not remembered.'});await expect(notice).toBeVisible();await expect.poll(()=>page.evaluate(()=>window.providerWrites.length)).toBe(2);
 if(newerReadFailure){await page.route('**/auth/v1/token*',r=>r.fulfill({json:session}));await page.evaluate(()=>{const original=indexedDB.open.bind(indexedDB);window.providerReadFailures=0;indexedDB.open=(...args)=>{if(!window.providerReadFailures){window.providerReadFailures++;throw new DOMException('fixture','SecurityError');}return original(...args);};});await page.evaluate(async()=>{const {supabase}=await import('/src/lib/supabase.ts');await supabase.auth.signInWithPassword({email:'fixture@example.invalid',password:'fixture'});});await expect.poll(()=>page.evaluate(()=>window.providerReadFailures)).toBe(1);}
 await page.evaluate(()=>window.finishProviderSecond());await expect.poll(async()=>(await stored(page)).public.tabs.length).toBe(3);
 if(newerReadFailure)await expect(notice).toBeVisible();else await expect(notice).toHaveCount(0);await add(page);await page.clock.fastForward(250);
 if(newerReadFailure){expect((await stored(page)).public.tabs).toHaveLength(3);await expect(notice).toBeVisible();await notice.getByRole('button',{name:'Retry',exact:true}).click();await page.getByRole('dialog',{name:'Restore remembered reading setups'}).getByRole('button',{name:'Restore setups',exact:true}).click();await page.clock.fastForward(250);}
 await expect.poll(async()=>(await stored(page)).public.tabs.length).toBe(4);
});
