test('provider continuous actual checkpoints commit the current projection at the2s maximum without lifecycle flush',async({page})=>{
 await setup(page);await add(page);await settled(page);const clockStart=Date.now();await page.clock.install({time:clockStart});await page.clock.pauseAt(clockStart+1000);await page.evaluate(()=>{window.providerLifecycle=0;window.addEventListener('pagehide',()=>window.providerLifecycle++);document.addEventListener('visibilitychange',()=>window.providerLifecycle++);});await add(page);
 for(let i=1;i<=13;i++){await page.clock.fastForward(150);await tabs(page).nth(i%2?0:2).click();}
 const keys=await tabs(page).evaluateAll(nodes=>nodes.map(node=>node.dataset.workspaceTab)),selected=await tabs(page).evaluateAll(nodes=>nodes.find(node=>node.getAttribute('aria-selected')==='true').dataset.workspaceTab);expect((await stored(page)).public.tabs).toHaveLength(2);await page.clock.fastForward(49);expect((await stored(page)).public.tabs).toHaveLength(2);await page.clock.fastForward(1);await expect.poll(async()=>{const pub=(await stored(page)).public;return {keys:pub.tabs.map(tab=>tab.tabKey),active:pub.activeTabKey};}).toEqual({keys,active:selected});expect(await page.evaluate(()=>window.providerLifecycle)).toBe(0);
});
async function gateFirstWorkspaceOpen(page){await page.addInitScript(()=>{const original=indexedDB.open.bind(indexedDB),pending=[];let released=false;window.gatedWorkspaceOpens=0;indexedDB.open=(...args)=>{if(released)return original(...args);window.gatedWorkspaceOpens++;let request;const callbacks={},proxy={};for(const key of ['result','transaction','error'])Object.defineProperty(proxy,key,{get:()=>request?.[key]});for(const event of ['onsuccess','onerror','onblocked','onupgradeneeded'])Object.defineProperty(proxy,event,{set:fn=>callbacks[event]=fn,get:()=>callbacks[event]});pending.push(()=>{request=original(...args);for(const event of ['onsuccess','onerror','onblocked','onupgradeneeded'])request[event]=eventObject=>callbacks[event]?.call(proxy,eventObject);});return proxy;};window.releaseDeviceBootstrap=()=>{released=true;for(const begin of pending)begin();};});}
