 await setup(page);await seed(page,publicSetup(choice==='victim'?12:2));await gateFirstWorkspaceOpen(page);const clockStart=Date.now();await page.clock.install({time:clockStart});await page.clock.pauseAt(clockStart+1000);await page.goto('/');await expect.poll(()=>page.evaluate(()=>window.gatedWorkspaceOpens)).toBe(2);await page.getByRole('button',{name:'Next chapter',exact:true}).click();await page.evaluate(()=>window.releaseDeviceBootstrap());const notice=page.getByRole('status').filter({hasText:'Remembered reading setups are ready.'});await expect(notice).toBeVisible();await notice.getByRole('button',{name:'Retry',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Restore remembered reading setups'});await expect(dialog).toBeVisible();await page.goBack();const chapter=()=>page.evaluate(()=>history.state.usr.scribeswellReader.panes[0].ref.target.chapter);await expect.poll(chapter).toBe(1);
 if(choice==='accept')await dialog.getByRole('button',{name:'Restore setups',exact:true}).click();else await dialog.getByRole('button',{name:/Close remembered tab/}).first().click();await expect(tabs(page)).toHaveCount(1);expect(await chapter()).toBe(1);await dialog.getByRole('button',{name:'Cancel',exact:true}).click();await notice.getByRole('button',{name:'Retry',exact:true}).click();await expect(dialog).toBeVisible();if(choice==='accept')await dialog.getByRole('button',{name:'Restore setups',exact:true}).click();else await dialog.getByRole('button',{name:/Close remembered tab/}).first().click();await expect(tabs(page)).toHaveCount(choice==='accept'?3:12);expect(await chapter()).toBe(1);
